// ---- China proper building blocks for imperial dynasties --------------------------------------------------------
const R = (polity: string, rings: C[], label?: LonLat, extra: Partial<Region> = {}): Region => ({ polity, rings, label, ...extra });

// ---- Pre-imperial maps: 夏, 商, 西周, 春秋, 战国初期 -----------------------------------------------------------------------
// Border chains were traced on the terrain model (mountain crests, rivers in their valleys) and on river lines for the
// plains (长江, 淮河, and the Yellow River on its period course), then simplified to 0.01°. Borders across open plains
// follow 谭其骧《中国历史地图集》 and standard textbook maps. Each chain is shared by the two regions it separates (reversed
// where needed), so neighbours meet without gaps or overlaps; `loop` joins chains end to start into a ring.
const loop = (...parts: C[]): C => parts.flatMap((p, i) => (i ? p.slice(1) : p)).slice(0, -1);

